INVENTORY_REL = "projects/sci-assistant/config/reagent_inventory.yaml"


def load_inventory(path=None):
    import yaml
    p = path or os.path.join(K.VAULT, INVENTORY_REL)
    if not os.path.isfile(p):
        return []
    with open(p, encoding="utf-8") as f:
        data = yaml.safe_load(f) or {}
    return data.get("reagents") or []


def attach_inventory(profile, base_dir=None):
    """把采购入库表提取的试剂并进档案（只补缺，不覆盖手写条目）。

    🔴 采购记录 ≠ 现有库存：这些条目 status=purchased，命中时只报 purchased。
    """
    rel = (profile or {}).get("reagents_source")
    if not rel:
        return profile
    p = rel if os.path.isabs(rel) else os.path.join(K.VAULT, rel)
    if not os.path.isfile(p) and base_dir:
        p = os.path.join(base_dir, os.path.basename(rel))
    inv = load_inventory(p)
    if not inv:
        return profile
    lab = profile.get("lab") or profile
    have = {norm(e.get("name")) for e in (lab.get("reagents") or [])
            if isinstance(e, dict)}
    added = 0
    for r in inv:
        name = str(r.get("name") or "").strip()
        if not name or norm(name) in have:
            continue
        lab.setdefault("reagents", []).append({
            "name": name,
            "spec": r.get("spec") or "",
            "cas": r.get("cas") or "",
            "aliases": r.get("aliases") or [],
            "qty": r.get("qty"),
            "last_in": r.get("last_in") or "",
            "status": "purchased",
            "source": "purchase_inventory",
        })
        have.add(norm(name))
        added += 1
    try:
        shown = os.path.relpath(p, K.VAULT)
    except ValueError:            # 测试用临时盘与库不在同一盘符
        shown = p
    profile["_inventory_meta"] = {"file": shown,
                                  "records": len(inv), "added": added}
    return profile


