# ---------------------------------------------------------------- 归一与匹配

def norm(s):
    return re.sub(r"\s+", " ", str(s or "")).strip().lower()


def families(text):
    """把一段文字映射到同义类集合。"""
    t = norm(text)
    out = set()
    for fam, keys in SYNONYMS.items():
        if any(k in t for k in keys):
            out.add(fam)
    return out


def profile_entries(profile):
    """把档案拉平成 [(kind, name, model, caps, extra)]；kind=equipment/characterization/reagent。"""
    out = []
    lab = (profile or {}).get("lab") or profile or {}
    for key, kind in (("equipment", "equipment"), ("characterization", "characterization"), ("compute", "compute"),
                      ("reagents", "reagent"), ("materials_inventory", "reagent")):
        for it in lab.get(key) or []:
            if isinstance(it, dict):
                name = it.get("name") or it.get("type") or ""
                model = it.get("model") or ""
                caps = it.get("capabilities") or it.get("aliases") or []
                out.append({"kind": kind, "name": name, "model": model,
                            "caps": caps, "status": str(it.get("status") or "available"),
                            "raw": it})
            else:
                out.append({"kind": kind, "name": str(it), "model": "",
                            "caps": [], "status": "available", "raw": it})
    # status=unavailable 的条目直接剔除（不能算可用）
    return [e for e in out if e["status"] != "unavailable"]


def _status_for(e, reason):
    st = e.get("status") or "available"
    if st == "purchased":
        return "purchased", e, f"{reason}；采购记录命中，**库存余量需确认**"
    if st in ("send-out", "restricted", "shared"):
        label = {"send-out": "送检", "restricted": "需审批", "shared": "共用"}[st]
        return "partial", e, f"{reason}；状态={label}"
    return "available", e, reason


def _entry_text(e):
    return (norm(e["name"]) + " " + norm(e["model"]) + " " +
            " ".join(norm(c) for c in (e["caps"] or [])))


def inventory_complete(profile):
    """试剂清单是否已登记完整。未声明 = 不完整（保守：未命中只能报 unregistered）。"""
    lab = (profile or {}).get("lab") or profile or {}
    meta = lab.get("reagents_meta") or {}
    return bool(meta.get("inventory_complete"))


def add_reagents_text(text, items):
    """把试剂条目插进 `reagents:` 块（文本级改写，保留其余注释与排版）。

    items: [{"name":..,"spec":..,"qty":..}]，只写非空字段。
    返回新文本；调用方负责 yaml.safe_load 复核后再落盘。
    """
    lines = text.split("\n")
    idx = next((i for i, l in enumerate(lines) if re.match(r"^reagents\s*:", l)), None)
    if idx is None:
        raise ValueError("lab_profile 里找不到顶层 `reagents:` 键")
    end = idx + 1
    while end < len(lines):
        ln = lines[end]
        if ln.strip() and not ln.startswith((" ", "\t")):
            break
        end += 1
    while end > idx + 1 and not lines[end - 1].strip():
        end -= 1
    block = ["reagents:"] + [ln for ln in lines[idx + 1:end] if ln.strip()]
    for it in items:
        block.append("  - name: " + json.dumps(str(it.get("name") or ""), ensure_ascii=False))
        if it.get("spec"):
            block.append("    spec: " + json.dumps(str(it["spec"]), ensure_ascii=False))
        if it.get("qty"):
            block.append("    qty: " + json.dumps(str(it["qty"]), ensure_ascii=False))
    return "\n".join(lines[:idx] + block + lines[end:])


def mark_reagents_complete_text(text, complete=True):
    """把 reagents_meta.inventory_complete 改成 true/false（没有该块则追加）。"""
    val = "true" if complete else "false"
    if re.search(r"^\s+inventory_complete\s*:", text, re.M):
        return re.sub(r"^(\s+inventory_complete\s*:).*$", r"\1 " + val, text, count=1, flags=re.M)
    block = ("\nreagents_meta:\n  inventory_complete: " + val +
             "\n  updated: " + datetime.date.today().isoformat() + "\n")
    return text.rstrip("\n") + "\n" + block


def match_item(required, entries, kind=None):
    """required: 文本；返回 (status, matched_entry, reason)。"""
    req_norm = norm(required)
    req_fams = families(required)
    req_in_situ = ("原位" in str(required)) or ("in situ" in req_norm)
    best = None
    for e in entries:
        if kind and e["kind"] != kind:
            continue
        text = _entry_text(e)
        # 单字名（如「水」）不做子串匹配：会命中「缩水甘油醚」这类无关条目
        hit = (len(req_norm) >= 2 and req_norm in text) or req_norm == norm(e["name"])
        if hit:
            if req_in_situ and "原位" not in text and "in situ" not in text:
                return "partial", e, "有同类设备，但档案未记录原位能力"
            return _status_for(e, "名称/型号直接命中")
        fam = req_fams & families(text)
        if fam:
            best = (e, fam)
    if best:
        e, fam = best
        note = f"同类（{','.join(sorted(fam))}）但非同名"
        if req_in_situ and "原位" not in _entry_text(e) and "in situ" not in _entry_text(e):
            return "partial", e, "有同类设备，但档案未记录原位能力"
        return _status_for(e, note)
    return "missing", None, "档案中无同类条目"


def required_items(method):
    """从方法记录里抽所需：设备类型/表征技术/材料。"""
    req = []
    for it in method.get("equipment") or []:
        if isinstance(it, dict):
            req.append(("equipment", str(it.get("type") or it.get("model") or "")))
        else:
            req.append(("equipment", str(it)))
    for it in method.get("characterization") or []:
        t = it.get("technique") if isinstance(it, dict) else it
        t = str(t or "")
        tl = t.lower()
        kind = "compute" if any(k in tl for k in
                                ("dft", "md", "aimd", "模拟", "计算", "机器学习",
                                 "mlff", "第一性原理")) else "characterization"
        req.append((kind, t))
    for it in method.get("materials") or []:
        if isinstance(it, dict) and it.get("name"):
            req.append(("reagent", str(it["name"])))
    # 去重（保序）
    seen, out = set(), []
    for k, v in req:
        key = (k, norm(v))
        if v and key not in seen:
            seen.add(key)
            out.append((k, v))
    return out


def match_method(method, profile):
    entries = profile_entries(profile)
    complete = inventory_complete(profile)
    rows = []
    for kind, name in required_items(method):
        status, e, reason = match_item(name, entries, kind)
        # 试剂未命中 ≠ 没有：清单未登记时只能说"未登记"（诊断意见 #1 短板 2）
        if status == "missing" and kind == "reagent" and not complete:
            status, reason = "unregistered", "试剂清单未登记（inventory_complete: false），不能判定为没有"
        rows.append({"kind": kind, "required": name, "status": status,
                     "matched": (e["name"] + ("（" + e["model"] + "）" if e["model"] else ""))
                     if e else "", "reason": reason})
    summary = {}
    for r in rows:
        summary[r["status"]] = summary.get(r["status"], 0) + 1
    return rows, summary


# ---------------------------------------------------------------- 档案自检

def profile_check(profile):
    issues = []
    if profile is None:
        return ["档案不存在：" + PROFILE_REL]
    lab = profile.get("lab") or profile or {}
    if not (lab.get("equipment") or []):
        issues.append("equipment 为空：无法判断是否有电化学工作站/手套箱等")
    if not (lab.get("characterization") or []):
        issues.append("characterization 为空：无法判断 SEM/XRD/XPS 等")
    if not (lab.get("reagents") or lab.get("materials_inventory") or []):
        if inventory_complete(profile):
            issues.append("reagents/materials_inventory 为空但标记为已登记完整：请核对")
        else:
            issues.append("reagents 为空且 inventory_complete=false：试剂需求将报 unregistered"
                          "（不算缺失；补录用 --add-reagent）")
    if not (lab.get("constraints") or []):
        issues.append("constraints 为空：无原位/温湿度/安全限制记录")
    if not lab.get("name"):
        issues.append("lab.name 未填")
    return issues


# ---------------------------------------------------------------- 渲染

def render_report(method, rows, summary, profile):
    L = [f"# 实验室匹配：{method.get('name_zh')}", ""]
    L.append(f"> 方法 `{method.get('method_id')}` ｜ 类别 {method.get('category')} ｜ "
             f"来源 {method.get('source_ref')} ｜ {datetime.date.today().isoformat()}")
    lab_meta = (profile or {}).get("lab") or profile or {}
    lab_name = lab_meta.get("name") or lab_meta.get("owner") or "未命名实验室"
    L.append(f"> 实验室档案：{lab_name}（`{PROFILE_REL}`）")
    L.append("")
    L.append("## 汇总")
    L.append("")
    L.append("｜ 状态 ｜ 数量 ｜")
    L.append("|---|---|")
    for k in ("available", "partial", "purchased", "missing", "unregistered", "unknown"):
        if summary.get(k):
            L.append(f"| {k} | {summary[k]} |")
    L.append("")
    L.append("## 逐项")
    L.append("")
    L.append("| 类型 | 需要 | 状态 | 匹配 | 说明 |")
    L.append("|---|---|---|---|---|")
    for r in rows:
        L.append(f"| {r['kind']} | {r['required']} | {r['status']} | "
                 f"{r['matched'] or '—'} | {r['reason']} |")
    L.append("")
    L.append("## 处置建议（模板，不含库内证据）")
    L.append("")
    for r in rows:
        if r["status"] == "missing" and r["kind"] == "equipment":
            L.append(f"- 缺设备「{r['required']}」：借用/采购；若不可得，该方案不可执行。")
        elif r["status"] == "missing" and r["kind"] == "characterization":
            L.append(f"- 缺表征「{r['required']}」：送测或合作平台（需排期与费用）。")
        elif r["status"] == "missing" and r["kind"] == "compute":
            L.append(f"- 缺计算资源「{r['required']}」：用组内服务器/超算或合作。")
        elif r["status"] == "missing" and r["kind"] == "reagent":
            L.append(f"- 试剂「{r['required']}」未登记：先确认库存，再决定自购。")
        elif r["status"] == "unregistered" and r["kind"] == "reagent":
            L.append(f"- 试剂「{r['required']}」库存未登记：**不算缺失**，先登记"
                     f"（`python tools/sci_lab_match.py --add-reagent \"{r['required']}||\"`）再判断。")
        elif r["status"] == "purchased" and r["kind"] == "reagent":
            L.append(f"- 试剂「{r['required']}」：**有采购入库记录**（{r['matched']}），"
                     f"但入库≠现有余量，用前先确认。")
        elif r["status"] == "partial":
            L.append(f"- 「{r['required']}」：档案有同类（{r['matched']}），需确认型号/原位能力。")
    L.append("")
    L.append("## 边界")
    L.append("")
    L.append("- 只按 `lab_profile.yaml` 现有条目判断；设备/表征未写的一律 `missing`，**不假设有**。")
    L.append("- 试剂清单未登记（`reagents_meta.inventory_complete: false`）时，未命中的试剂报 "
             "`unregistered`（未登记），**不等于实验室没有**。")
    L.append("- `purchased` 表示**采购入库表**里有记录（含别名，如 ZnCl2→氯化锌），"
             "但入库≠现有余量，需人工确认。")
    L.append("- `partial` 表示同类但型号/能力未核对，使用前需确认具体参数。")
    L.append("- 试剂匹配是名称级，未核对纯度/危险性/库存。")
    L.append("")
    return "\n".join(L)


# ---------------------------------------------------------------- 试剂登记（写盘）

def parse_reagent_spec(s):
    """`名称|规格|数量` → dict（后两段可省）。"""
    parts = [p.strip() for p in str(s).split("|")]
    name = parts[0]
    if not name:
        raise ValueError("试剂名不能为空")
    return {"name": name,
            "spec": parts[1] if len(parts) > 1 else "",
            "qty": parts[2] if len(parts) > 2 else ""}


def add_reagents_cmd(profile_path, specs, mark_complete=False):
    """把试剂写回 lab_profile.yaml：先改写文本 → yaml 复核 → 备份 → 落盘 → 再读回。"""
    import shutil
    import yaml
    p = profile_path or os.path.join(K.VAULT, PROFILE_REL)
    if not os.path.isfile(p):
        raise SystemExit(f"[!] 档案不存在：{p}")
    text = K.read_text(p)
    old = load_profile(p) or {}
    old_lab = (old.get("lab") or old) or {}
    old_n = len(old_lab.get("reagents") or [])
    items = [parse_reagent_spec(s) for s in specs]
    new = text
    if items:
        new = add_reagents_text(new, items)
    if mark_complete:
        new = mark_reagents_complete_text(new, True)
    expect = old_n + len(items)
    try:
        got = len((yaml.safe_load(new) or {}).get("reagents") or [])
    except Exception as e:  # noqa: BLE001
        raise SystemExit(f"[!] 改写后 YAML 解析失败，未写盘：{e}")
    if got != expect:
        raise SystemExit(f"[!] 改写后条目数 {got} != 预期 {expect}，未写盘")
    bak_dir = os.path.join(K.VAULT, "_scratch", "backup")
    os.makedirs(bak_dir, exist_ok=True)
    bak = os.path.join(bak_dir, "lab_profile-"
                       + datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f") + ".yaml")
    shutil.copy2(p, bak)
    K.write_text_verified(p, new)
    back = len(((load_profile(p) or {}).get("reagents")) or [])
    print(f"[ok] 试剂登记：{old_n} → {back} 条（预期 {expect}）")
    print(f"     备份：{os.path.relpath(bak, K.VAULT)}")
    if not inventory_complete(load_profile(p)):
        print("     ⚠️ inventory_complete 仍为 false：未命中的试剂继续报 unregistered；"
              "确认清单完整后加 --mark-reagents-complete")
    return 0 if back == expect else 1


# ---------------------------------------------------------------- 自检

def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    profile = {"lab": {"name": "测试实验室",
                       "equipment": [{"name": "电化学工作站", "model": "CHI760E",
                                      "capabilities": ["CV", "EIS", "LSV"]},
                                     {"name": "手套箱", "model": "MBraun"}],
                       "characterization": [{"name": "X射线衍射仪", "model": "Bruker D8",
                                             "capabilities": ["XRD"]},
                                            {"name": "扫描电镜", "model": "Zeiss",
                                             "capabilities": ["SEM", "EDX"]}],
                       "reagents": [{"name": "乙酸钾"}, {"name": "Zn(Ac)2"}],
                       "constraints": ["无原位 Raman"]}}
    method = {"method_id": "source:X", "name_zh": "测试方法", "category": "合成",
              "source_ref": "[[sources/X]]",
              "equipment": [{"type": "电化学工作站"}],
              "characterization": [{"technique": "XRD"}, {"technique": "SEM"},
                                   {"technique": "Raman"}],
              "materials": [{"name": "KAc"}, {"name": "Zn(Ac)2"}, {"name": "TMP"}]}
    rows, summary = match_method(method, profile)
    by = {r["required"]: r["status"] for r in rows}
    chk("匹配：工作站 available", by.get("电化学工作站") == "available")
    chk("匹配：XRD 英文缩写命中中文条目", by.get("XRD") == "available")
    chk("匹配：SEM available", by.get("SEM") == "available")
    chk("匹配：Raman 档案中无 ⇒ missing", by.get("Raman") == "missing")
    chk("匹配：KAc 未在档案且清单未登记 ⇒ unregistered（不算缺失）",
        by.get("KAc") == "unregistered")
    chk("汇总：状态计数一致", sum(summary.values()) == len(rows))
    chk("档案自检：完整档案无问题", profile_check(profile) == [])
    chk("档案自检：空档案报缺失", len(profile_check({})) >= 4)

    # 清单登记完整后，未命中才能报 missing
    profile2 = dict(profile)
    profile2["lab"] = dict(profile["lab"])
    profile2["lab"]["reagents_meta"] = {"inventory_complete": True}
    rows2, _ = match_method(method, profile2)
    by2 = {r["required"]: r["status"] for r in rows2}
    chk("匹配：inventory_complete=true 时未命中 ⇒ missing", by2.get("KAc") == "missing")

    # 试剂登记：文本级改写（保留注释），写后 yaml 可解析且条目数正确
    import yaml as _yaml
    base = ("# 注释要保留\nname: t\nreagents: []\n\ncharacterization:\n"
            "  - name: XRD\n    status: available\n")
    t1 = add_reagents_text(base, [{"name": "ZnSO4·7H2O", "spec": "AR", "qty": "500 g"},
                                  {"name": "KOH", "spec": "GR", "qty": "1 kg"}])
    d1 = _yaml.safe_load(t1)
    chk("登记：空列表改写成块且 yaml 可解析、条目数=2",
        len(d1.get("reagents") or []) == 2 and "# 注释要保留" in t1
        and (d1.get("characterization") or [{}])[0].get("name") == "XRD")
    t2 = add_reagents_text(t1, [{"name": "乙酸钾", "spec": "AR", "qty": "100 g"}])
    d2 = _yaml.safe_load(t2)
    chk("登记：已有块上追加，条目数=3", len(d2.get("reagents") or []) == 3
        and d2["reagents"][2]["name"] == "乙酸钾")
    t3 = mark_reagents_complete_text(t2, True)
    chk("登记：inventory_complete 置 true 且可解析",
        (_yaml.safe_load(t3).get("reagents_meta") or {}).get("inventory_complete") is True)

    md = render_report(method, rows, summary, profile)
    chk("渲染：含汇总表与逐项表且列出 unregistered",
        "## 汇总" in md and "## 逐项" in md and "unregistered" in md)

    # 采购入库表并入：别名命中 → purchased；已有同名条目不重复添加
    tmp2 = K.make_temp_dir(prefix="sci_lab_inv_")
    try:
        inv = os.path.join(tmp2, "reagent_inventory.yaml")
        with open(inv, "w", encoding="utf-8") as f:
            _yaml.dump({"reagents": [{"name": "氯化锌", "aliases": ["ZnCl2"],
                                      "spec": "100g", "qty": 1.0,
                                      "last_in": "2026-08-25", "cas": "7646-85-7"}]},
                       f, allow_unicode=True)
        prof3 = {"name": "t", "reagents": [], "equipment": [{"name": "手套箱"}],
                 "characterization": [{"name": "XRD"}], "constraints": ["无原位"],
                 "reagents_source": inv}
        p3 = attach_inventory(prof3)
        chk("入库表：并入并标记 purchased",
            (p3.get("_inventory_meta") or {}).get("added") == 1
            and any(e.get("source") == "purchase_inventory"
                    for e in (p3.get("reagents") or [])))
        m3 = {"method_id": "source:Y", "name_zh": "t", "category": "合成",
              "source_ref": "[[sources/Y]]", "equipment": [],
              "characterization": [], "materials": [{"name": "ZnCl2"}]}
        rows3, _ = match_method(m3, p3)
        chk("入库表：ZnCl2 通过别名命中 → purchased",
            rows3 and rows3[0]["status"] == "purchased", str(rows3))
        prof4 = {"name": "t", "reagents": [{"name": "氯化锌"}], "equipment": [{"name": "X"}],
                 "characterization": [{"name": "XRD"}], "constraints": ["c"],
                 "reagents_source": inv}
        p4 = attach_inventory(prof4)
        chk("入库表：手写同名条目不被重复添加",
            (p4.get("_inventory_meta") or {}).get("added") == 0
            and len(p4.get("reagents") or []) == 1)
    finally:
        K.remove_temp_dir(tmp2)
    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: {len(fails)} failure(s)")
    return 0 if not fails else 1


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="实验室条件匹配（Phase 2c）")
    ap.add_argument("--method", help="方法库 method_id")
    ap.add_argument("--profile", default=None, help="lab_profile.yaml 路径覆盖")
    ap.add_argument("--check", action="store_true", help="只检查档案完整性")
    ap.add_argument("--add-reagent", action="append", default=[], metavar="名称|规格|数量",
                    help="登记一条常备试剂（可重复；后两段可省），写回 lab_profile.yaml")
    ap.add_argument("--mark-reagents-complete", action="store_true",
                    help="把 reagents_meta.inventory_complete 置 true（清单已列全时用）")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--no-write", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args(argv)

    if args.selftest:
        return _selftest()

    if args.add_reagent or args.mark_reagents_complete:
        return add_reagents_cmd(args.profile, args.add_reagent,
                                mark_complete=args.mark_reagents_complete)

    profile = load_profile(args.profile)
    if args.check or not args.method:
        issues = profile_check(profile)
        if args.json:
            print(json.dumps({"profile": args.profile or PROFILE_REL,
                              "issues": issues}, ensure_ascii=False, indent=2))
        else:
            print(f"[profile] {args.profile or PROFILE_REL}")
            inv = (profile or {}).get("_inventory_meta") or {}
            if inv:
                print(f"  采购入库表：{inv.get('file')}（{inv.get('records')} 条，"
                      f"新增 {inv.get('added')} 条，状态 purchased）")
            if not issues:
                print("  ✅ 必填项齐全")
            for i in issues:
                print(f"  - {i}")
        return 0 if profile else 1

    cfg = load_config()
    methods = {m.get("method_id"): m for m in load_methods(cfg)}
    m = methods.get(args.method)
    if not m:
        raise SystemExit(f"[!] 方法库找不到：{args.method}")
    rows, summary = match_method(m, profile)
    md = render_report(m, rows, summary, profile)
    if args.json:
        print(json.dumps({"method": m.get("method_id"), "summary": summary,
                          "rows": rows}, ensure_ascii=False, indent=2))
    if not args.no_write:
        out = os.path.join(K.VAULT, "projects/sci-assistant/lab_match",
                           f"{datetime.date.today().isoformat()}-{m.get('method_id').split(':')[-1][:40]}.md")
        os.makedirs(os.path.dirname(out), exist_ok=True)
        K.write_text_verified(out, md + "\n")
        print(f"[ok] 匹配报告：{os.path.relpath(out, K.VAULT)}")
        print(f"     available={summary.get('available', 0)} "
              f"partial={summary.get('partial', 0)} "
              f"purchased={summary.get('purchased', 0)} "
              f"missing={summary.get('missing', 0)} "
              f"unregistered={summary.get('unregistered', 0)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
